import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷一·10","description":"易小帖 - 卷一·10","frontmatter":{"title":"卷一·10","description":"易小帖 - 卷一·10"},"headers":[],"relativePath":"zh/classics/yixiaotie/010.md","filePath":"zh/classics/yixiaotie/010.md"}'),o={name:"zh/classics/yixiaotie/010.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷一·10",tabindex:"-1"},[r("卷一·10 "),e("a",{class:"header-anchor",href:"#卷一·10","aria-label":"Permalink to “卷一·10”"},"​")],-1),e("p",null,"易有五易（見《仲氏易》首），雖去入兩音只是一義，古變易之易皆讀去聲，如班固《東都賦》紛綸後闢與蹈一聖之險易，押可驗。若謂漢晉以前無變易之解，則《系詞》雲神無方而易無體，此夫子之解義也。若謂隋唐以後始有入聲之讀，則《系詞》雲「日新之謂盛德，生生之謂易」，又雲「乾坤毀則無以見易，無以見易則乾坤或幾乎息」，此夫子之讀音也。豎儒但觀一隙，不覯大通，偶聞易可讀異，便妄生議論，可鄙極矣。至若《說文》以蜥蜴為蜥易，此重傍省文之字，而楊升庵遂謂易是守宮之名，則《漢書‧食貨志》以疆埸為疆易，得毋易又是疆畔名乎（古重傍省文字，如欄干琅邪類）。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
